import csv, hashlib, json, math, random
from collections import Counter, defaultdict
from functools import lru_cache
from vs import refcorpus

PATH='/tmp/voy-piii.csv'
raw=open(PATH,'rb').read()
assert hashlib.sha256(raw).hexdigest()=='fe3f24a46dbc6b655eab8dbbd75addf84ee4a7dbd387ad802af75d02edfe5b4d'
table=list(csv.DictReader(raw.decode('utf-8-sig').splitlines())); alphabet=list(table[0]); allowed=set(alphabet)
for row in table:
 for c in row: row[c]=row[c].strip()
BOOKS=('la_augustine','la_erasmus','la_vulg_daniel','la_patrick','la_vulg_esther_a')
REFERENCE=BOOKS+('la_vulg_jonah',)
TRAIN=12000; TEST=4000; SWEEPS=2; SHUFFLES=19; SEEDS=(41,71,103)
def book(id): return ''.join(c for b in refcorpus.blocks_of(id) for c in b if c in allowed)
pins={e['id']:e for e in refcorpus.pins()}
for k in REFERENCE:
    with open(pins[k]['file'],'rb') as f:
        assert hashlib.sha256(f.read()).hexdigest()==pins[k]['sha256'], k
texts={k:book(k) for k in REFERENCE}

@lru_cache(maxsize=None)
def model(exclude):
    ref=''.join(texts[k] for k in REFERENCE if k!=exclude)
    prior=Counter(ref); rank=sorted(alphabet,key=lambda x:(-prior[x],x)); count=Counter(zip(ref,ref[1:])); sums=Counter(ref[:-1]); n=len(alphabet)
    score={(a,b):math.log((count[a,b]+1)/(sums[a]+n)) for a in alphabet for b in alphabet}
    return prior,rank,score

def make_plain(rng, real, kind, prior, score):
    if kind=='real': return real[:TRAIN+TEST]
    if kind=='iid': return ''.join(rng.choices(alphabet,weights=[prior[c] for c in alphabet],k=TRAIN+TEST))
    # Markov null preserves fitted first-order transitions but has no syntax or meaning.
    text=[rng.choices(alphabet,weights=[prior[c] for c in alphabet])[0]]
    for _ in range(TRAIN+TEST-1):
        text.append(rng.choices(alphabet,weights=[math.exp(score[text[-1],c]) for c in alphabet])[0])
    return ''.join(text)

def loss(seq,mapping,score,default):
    decoded=[mapping.get(s,default) for s in seq]
    return -sum(score[a,b] for a,b in zip(decoded,decoded[1:]))/max(1,len(seq)-1)

def initial(groups,rank):
    cnt=Counter(groups); ordered=sorted(cnt,key=lambda x:(-cnt[x],x)); return {x:rank[i] if i<len(rank) else rank[0] for i,x in enumerate(ordered)}

def optimize(groups,key,score):
    # Coordinate ascent: count all adjacent-group transitions; optimize one assignment
    # at a time. Exact local score includes self transitions only once.
    edges=Counter(zip(groups,groups[1:])); outgoing=defaultdict(Counter); incoming=defaultdict(Counter)
    for (a,b),n in edges.items(): outgoing[a][b]=n; incoming[b][a]=n
    for _ in range(SWEEPS):
      for g in sorted(key):
        def contribution(c):
            return sum(n*score[c, c if h==g else key[h]] for h,n in outgoing[g].items()) + sum(n*score[key[h],c] for h,n in incoming[g].items() if h!=g)
        key[g]=max(alphabet,key=lambda c:contribution(c))
    return key

def experiment(book_id,ncol,strategy,seed,kind):
    prior,rank,score=model(book_id); rng=random.Random(seed); plain=make_plain(random.Random(seed+100000),texts[book_id],kind,prior,score)
    assert len(plain)==TRAIN+TEST
    cols=rng.sample(range(len(table)),ncol)
    selected=[rng.randrange(ncol) if strategy=='random' else i%ncol for i in range(len(plain))]
    pairs=[(cols[c],table[cols[c]][letter]) for c,letter in zip(selected,plain)]
    # Search sees only each artificial word, never the generating column or plaintext.
    words=[word for _,word in pairs]; gr=[w[-2:] for w in words]
    base=initial(gr[:TRAIN],rank); opt=optimize(gr[:TRAIN],dict(base),score)
    # Same-cipher known-column frequency benchmark, a deliberately strong oracle.
    counts=defaultdict(Counter)
    for col,word in pairs[:TRAIN]: counts[col][word]+=1
    oracle={}
    for col,cnt in counts.items():
      for w,letter in zip(sorted(cnt,key=lambda w:(-cnt[w],w)),rank): oracle[col,w]=letter
    true=plain[TRAIN:]; held=gr[TRAIN:]; bseq=[base.get(x,rank[0]) for x in held]; oseq=[opt.get(x,rank[0]) for x in held]
    op=[oracle.get(x,rank[0]) for x in pairs[TRAIN:]]
    # Shuffle ciphertext groups at test time without knowing columns.
    null=[]
    for _ in range(SHUFFLES):
      shuffled=held[:];rng.shuffle(shuffled);null.append(loss(shuffled,opt,score,rank[0]))
    actual=loss(held,opt,score,rank[0]); p=(1+sum(v<=actual for v in null))/(SHUFFLES+1)
    # If the selection period is known, shuffle only within position modulo that period.
    # This preserves cycle-specific token marginals but does not give column IDs to the decoder.
    period_null=[]
    for _ in range(SHUFFLES):
      shuffled=held[:]
      for offset in range(ncol):
        ids=list(range(offset,len(held),ncol)); vals=[held[i] for i in ids]; rng.shuffle(vals)
        for i,v in zip(ids,vals): shuffled[i]=v
      period_null.append(loss(shuffled,opt,score,rank[0]))
    period_p=(1+sum(v<=actual for v in period_null))/(SHUFFLES+1)
    def acc(a): return round(sum(x==y for x,y in zip(a,true))/len(true),4)
    # Measures compatibility with actual held-out word/letter observations, including collisions.
    pertype=defaultdict(list)
    for w,x,y in zip(words[TRAIN:],oseq,true): pertype[w].append(x==y)
    return {'book':book_id,'columns':ncol,'selection':strategy,'seed':seed,'kind':kind,
       'cipher_train_types':len(set(words[:TRAIN])),'suffix_groups':len(set(gr[:TRAIN])),
       'unseen_suffix_fraction':round(sum(g not in opt for g in held)/len(held),4),
       'baseline_accuracy':acc(bseq),'context_accuracy':acc(oseq),'oracle_accuracy':acc(op),
       'context_type_accuracy_macro':round(sum(sum(v)/len(v) for v in pertype.values())/len(pertype),4),
       'decoded_alphabet_size':len(set(oseq)), 'decoded_max_letter_share':round(max(Counter(oseq).values())/len(oseq),4),
       'baseline_train_nll':round(loss(gr[:TRAIN],base,score,rank[0]),5),'baseline_test_nll':round(loss(held,base,score,rank[0]),5),'context_train_nll':round(loss(gr[:TRAIN],opt,score,rank[0]),5),
       'context_test_nll':round(actual,5),'shuffle_mean_nll':round(sum(null)/len(null),5),'shuffle_p':p,
       'period_shuffle_mean_nll':round(sum(period_null)/len(period_null),5),'period_shuffle_p':period_p}

if __name__=='__main__':
 print(json.dumps({'table_sha256':hashlib.sha256(raw).hexdigest(),'books':{k:len(v) for k,v in texts.items()},'train':TRAIN,'test':TEST,'sweeps':SWEEPS,'shuffles':SHUFFLES,
  'rows':[experiment(b,n,mode,s,k) for b in BOOKS for n in (10,24,131) for mode in ('random','sequential') for s in SEEDS for k in ('real','iid','markov')]},indent=2))
